(7456693, 1181489, 12611, '<td valign="top">The details are fantastic. These gallery shots are easy to take but hard to present well- and you have done so- the muted complimentary colors, the grain, and the shadows,  the "wolf of art" if you will, ready to swallow up the unsuspecting patron.</td>', 'The details are fantastic. These gallery shots are easy to take but hard to present well- and you have done so- the muted complimentary colors, the grain, and the shadows,  the "wolf of art" if you will, ready to swallow up the unsuspecting patron.', '2016-05-25 16:15:26.000000', NULL, 1),
(7456694, 1181440, 12611, '<td valign="top">beautifully presented. super color and blur. I''d be shocked if this isn''t on the front page.</td>', 'beautifully presented. super color and blur. I''d be shocked if this isn''t on the front page.', '2016-05-25 16:16:11.000000', NULL, 1),
(7456695, 1181202, 12611, '<td valign="top">the choice of color, and the tonal enhancements, really work here, they add depth and reality, keep it from being campy, and add a sense of creepiness that only the daylight can provide in the deep woods.</td>', 'the choice of color, and the tonal enhancements, really work here, they add depth and reality, keep it from being campy, and add a sense of creepiness that only the daylight can provide in the deep woods.', '2016-05-25 16:17:45.000000', NULL, 1),
